// editorial/emails/newsletter.tsx, from hyperelements.dev/templates. Replace the brand block with your own brand.

import { lint } from "@hyper-elements/lint";
import { Button, Column, Divider, Email, Heading, Image, Link, Row, Section, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { field, formatDate, template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Orbit",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#0b1020",
      primary: "#4f46e5",
      primaryForeground: "#ffffff",
      border: "#e2e5ee",
      muted: "#5b6478",
      surface: "#f4f5fa",
      accent: "#2dd4bf",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "Inter, 'Helvetica Neue', Arial, sans-serif" },
    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 40 },
    radii: { sm: 6, md: 12 },
    elements: {
      Heading: {
        fontWeight: 700,
        by: {
          level: {
            1: { fontSize: 32, lineHeight: 1.15 },
            2: { fontSize: 24, lineHeight: 1.25 },
            3: { fontSize: 19, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/orbit/logo.png", width: 480, height: 120, alt: "Orbit" },
  address: "1 Main Street, Springfield",
  links: { site: "https://orbit.example", domains: ["orbit.example", "*.orbit.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
  ],
};
// brand: end

// From _categories/newsletter.ts
const newsletter = {
  group: "Content",
  label: "Newsletter",
  roots: ["Email", "Page"],
  useWhen: "A regular issue of written news: a subject, a lead, and sections the writer fills in",
  avoidWhen: "One announcement (use announcement), or a summary built from data (use digest)",
  required: {
    subject: prop.text({ label: "Subject", required: true, maxLength: 70 }),
    preview: prop.text({ label: "Preview text", required: true, maxLength: 120 }),
  },
  example: {
    subject: "What's new this month",
    preview: "Faster exports, notes in your own voice, and a date for the open house",
  },
} as const;

// The template
const EDITORIAL_WIDTH = 600;
const EDITORIAL_ASSETS = "https://hyperelements.dev/generated/kits/assets/kits/editorial/";

function editorialNewsletter(brand: Brand) {
  const href = (to: string | { href: string }) => {
    const url = new URL(typeof to === "string" ? to : to.href, brand.links.site);
    for (const [key, value] of Object.entries(brand.links.params ?? {})) url.searchParams.set(key, value);
    return url.toString();
  };
  const kicker = { fontSize: token("fontSizes.small"), fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase" } as const;
  return template({
    id: "templates.EditorialNewsletterEmail",
    version: "1.0.0",
    label: "Newsletter",
    description: "A regular issue: a masthead with the issue and date, a lead story, more stories with thumbnails, a closing note, and an unsubscribe footer",
    guidance: "Friendly and plain: sentence case, no exclamation marks. The lead is the issue's one big story; each other story is a title and two sentences at most.",
    root: "Email",
    fields: {
      ...newsletter.required,
      issue: prop.text({ label: "Issue", required: true, maxLength: 20 }),
      date: prop.date({ label: "Sent on", required: true }),
      lead: prop.object(
        {
          kicker: prop.text({ label: "Kicker", maxLength: 30 }),
          title: prop.text({ label: "Title", required: true, maxLength: 80 }),
          summary: prop.text({ label: "Summary", required: true, maxLength: 300 }),
          href: prop.link({ label: "Link", required: true }),
          cta: prop.text({ label: "Button", maxLength: 30, default: "Read the story" }),
        },
        { label: "Lead story", required: true },
      ),
      stories: prop.list(
        prop.object(
          {
            title: prop.text({ label: "Title", required: true, maxLength: 80 }),
            summary: prop.text({ label: "Summary", required: true, maxLength: 200 }),
            image: field.image({ label: "Thumbnail", aspect: { min: 0.9, max: 1.5 }, minWidth: 280, accepts: ["png", "jpeg"] }),
            href: prop.link({ label: "Link", required: true }),
          },
          { label: "Story" },
        ),
        { label: "More stories", min: 0, max: 4 },
      ),
      note: prop.object(
        {
          title: prop.text({ label: "Title", required: true, maxLength: 60 }),
          text: prop.text({ label: "Text", required: true, maxLength: 240 }),
          label: prop.text({ label: "Button", required: true, maxLength: 30 }),
          href: prop.link({ label: "Link", required: true }),
        },
        { label: "Closing note" },
      ),
    },
    rules: {
      plugins: { lint: lint({ kind: "marketing" }) },
      require: { lint: ["contrast", "text-size", "link-text", "alt-text", "unsubscribe", "lang"], core: ["layout/overflow"] },
      links: { domains: brand.links.domains, ...(brand.links.params ? { params: brand.links.params } : {}) },
      root: { lang: true, previewText: true },
    },
    example: {
      ...newsletter.example,
      issue: "No. 14",
      date: "2026-03-05",
      lead: {
        kicker: "This month",
        title: "Exports that finish before your coffee does",
        summary: "We rebuilt the export pipeline from the ground up. Big projects that took minutes now take seconds, and there's nothing to change in your settings to get it.",
        href: "/blog/faster-exports",
        cta: "Read about faster exports",
      },
      stories: [
        {
          title: "Notes that sound like you",
          summary: "Release notes now start from what you've written before, so a first draft already has your voice.",
          image: { src: `${EDITORIAL_ASSETS}recorder.png`, width: 1020, height: 900 },
          href: "/blog/your-voice",
