import { Column, Email, Heading, Image, LineBreak, Link, Row, Span, Table, TableCell, TableRow, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { formatDate, template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Oyen",
  theme: defineTheme({
    colors: {
      background: "#f3f1ec",
      foreground: "#1a1917",
      primary: "#b33a0b",
      primaryForeground: "#ffffff",
      border: "#d3cec4",
      muted: "#5f5b53",
      surface: "#ffffff",
      accent: "#ff5b1f",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "Inter, 'Helvetica Neue', Arial, sans-serif" },
    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 40 },
    radii: { sm: 0, md: 2 },
    elements: {
      Heading: {
        fontWeight: 800,
        by: {
          level: {
            1: { fontSize: 36, lineHeight: 1.15 },
            2: { fontSize: 26, lineHeight: 1.25 },
            3: { fontSize: 19, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/oyen/logo.png", width: 480, height: 120, alt: "Oyen" },
  address: "14 Foundry Lane, Pittsburgh",
  links: { site: "https://oyen.example", domains: ["oyen.example", "*.oyen.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-800.ttf", weight: 800, style: "normal" },
  ],
};
// brand: end

// From _categories/order-confirmation.ts
const orderConfirmation = {
  group: "Orders",
  label: "Order confirmation",
  roots: ["Email"],
  useWhen: "Confirming an order was placed: what's in it, what it costs, and where it's going",
  avoidWhen: "Proof of a payment for a subscription (use receipt), or an order on its way (use shipping)",
  required: {
    number: prop.text({ label: "Order number", required: true, maxLength: 20 }),
    placed: prop.date({ label: "Placed on", required: true }),
    items: prop.list(
      prop.object(
        {
          description: prop.text({ label: "Description", required: true, maxLength: 80 }),
          quantity: prop.number({ label: "Quantity", required: true, min: 1, integer: true }),
          price: prop.number({ label: "Unit price", required: true, min: 0 }),
        },
        { label: "Item" },
      ),
      { label: "Items", required: true, min: 1, max: 30 },
    ),
    currency: prop.choice(["USD", "EUR", "GBP"], { label: "Currency", default: "USD" }),
    shipTo: prop.object(
      {
        name: prop.text({ label: "Name", required: true, maxLength: 60 }),
