import type { ReactNode } from "react";
import { lint } from "@hyper-elements/lint";
import { Column, Email, Heading, Image, Link, Row, Table, TableCell, TableRow, Text, defineTheme, prop, token } from "@hyper-elements/react";
import type { Theme } from "@hyper-elements/react";
import { formatDate, template } from "@hyper-elements/react/template";

/** One font file a brand's theme needs: a TTF or OTF file, at one weight and style. */
type BrandFont = { family: string; src: string; weight: number; style: "normal" | "italic" };

type Brand = {
  name: string;
  /** A `defineTheme()` result holding the contract's tokens (`CONTRACT`). */
  theme: Theme;
  /** A PNG or JPEG file. */
  logo: { src: string; width: number; height: number; alt: string };
  /** The postal address footers show. */
  address?: string;
  /** The brand's site, and the hosts its links may go to (`acme.example`, or `*.acme.example`). */
  links: { site: string; domains: readonly string[]; params?: Readonly<Record<string, string>> };
  /** The language, as a BCP 47 tag: "en" where it isn't set. */
  lang?: string;
  dir?: "ltr" | "rtl" | "auto";
  fonts: BrandFont[];
};

// brand: start (replace with your own; every value below is used)
const brand: Brand = {
  name: "Pell & Ashby",
  theme: defineTheme({
    colors: {
      background: "#ffffff",
      foreground: "#1c1b19",
      primary: "#24513d",
      primaryForeground: "#ffffff",
      border: "#dad6cd",
      muted: "#66625a",
      surface: "#f6f4ef",
      accent: "#b9c7bc",
    },
    fonts: { body: "Inter, 'Helvetica Neue', Arial, sans-serif", heading: "'Source Serif 4', Georgia, 'Times New Roman', serif" },
    fontSizes: { body: 15, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 12, lg: 20, xl: 32 },
    radii: { sm: 0, md: 0 },
    elements: {
      Heading: {
        fontWeight: 600,
        by: {
          level: {
            1: { fontSize: 30, lineHeight: 1.15 },
            2: { fontSize: 22, lineHeight: 1.25 },
            3: { fontSize: 18, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/pell-ashby/logo.png", width: 480, height: 120, alt: "Pell & Ashby" },
  address: "3 Lincoln's Court, Philadelphia",
  links: { site: "https://pellashby.example", domains: ["pellashby.example", "*.pellashby.example"] },
  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
    { family: "Source Serif 4", src: "https://hyperelements.dev/generated/kits/assets/fonts/SourceSerif4-600.ttf", weight: 600, style: "normal" },
  ],
};
// brand: end

// From _categories/receipt.ts
const receipt = {
  group: "Billing",
  label: "Receipt",
  roots: ["Email", "Document"],
  useWhen: "Proof of a payment already made: what was bought, what it cost, and when it was paid",
  avoidWhen: "A bill still to be paid (use invoice), or an order that hasn't been charged yet (use order-confirmation)",
  required: {
    number: prop.text({ label: "Receipt number", required: true, maxLength: 20 }),
    paid: prop.date({ label: "Paid on", required: true }),
    items: prop.list(
      prop.object(
        {
          description: prop.text({ label: "Description", required: true, maxLength: 80 }),
          quantity: prop.number({ label: "Quantity", required: true, min: 1, integer: true }),
          price: prop.number({ label: "Unit price", required: true, min: 0 }),
        },
        { label: "Item" },
      ),
      { label: "Items", required: true, min: 1, max: 30 },
    ),
    currency: prop.choice(["USD", "EUR", "GBP"], { label: "Currency", default: "USD" }),
  },
  example: {
    number: "R-20418",
    paid: "2026-03-04",
    items: [
      { description: "Pro plan, monthly", quantity: 1, price: 24 },
      { description: "Extra seats", quantity: 3, price: 8 },
    ],
  },
} as const;

// From minimal/parts.tsx
/** A link's address: a path on the brand's site, or a full URL, with the brand's required parameters. */
function minimalHref(brand: Brand, to: string | { href: string }): string {
  const url = new URL(typeof to === "string" ? to : to.href, brand.links.site);
  for (const [key, value] of Object.entries(brand.links.params ?? {})) url.searchParams.set(key, value);
  return url.toString();
}

/** The rules every Minimal email holds to. */
function minimalRules(brand: Brand) {
  return {
    plugins: { lint: lint() },
    require: { lint: ["contrast", "text-size", "link-text", "alt-text"], core: ["layout/overflow"] },
    links: { domains: brand.links.domains, ...(brand.links.params ? { params: brand.links.params } : {}) },
    root: { lang: true as const, previewText: true as const },
  };
}

/** The email around a Minimal message: the logo, one card holding the message (with a band of the brand's color
 * across its top, where it has one), and the brand's address and site under it. */
function minimalEmail(brand: Brand, email: { title: string; preview: string; band?: ReactNode; children: ReactNode; footer?: ReactNode }) {
  return (
    <Email
      width={560}
      title={email.title}
      previewText={email.preview}
      lang={brand.lang ?? "en"}
      {...(brand.dir ? { dir: brand.dir } : {})}
      theme={brand.theme}
      fonts={brand.fonts}
      style={{ backgroundColor: token("colors.surface"), fontSize: token("fontSizes.body"), lineHeight: token("lineHeights.body") }}
    >
      <Column style={{ padding: [token("spacing.xl"), token("spacing.md"), token("spacing.lg")], gap: token("spacing.lg") }}>
        <Column style={{ alignItems: "center" }}>
          <Image src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }} alt={brand.logo.alt} style={{ width: 150 }} />
        </Column>
        <Column style={{ backgroundColor: token("colors.background"), borderRadius: token("radii.md"), border: { width: 1, style: "solid", color: token("colors.border") } }}>
          {email.band ? (
            <Column
              style={{
                backgroundColor: token("colors.primary"),
                color: token("colors.primaryForeground"),
                padding: [token("spacing.xl"), token("spacing.xl"), token("spacing.lg")],
                gap: token("spacing.sm"),
                borderRadius: { topLeft: token("radii.md"), topRight: token("radii.md") },
              }}
            >
              {email.band}
            </Column>
          ) : null}
          <Column style={{ padding: token("spacing.xl"), gap: token("spacing.md") }}>{email.children}</Column>
        </Column>
        <Column style={{ gap: token("spacing.xs") }}>
          {email.footer ?? null}
          <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "center" }}>
            {brand.name}
            {brand.address ? ` · ${brand.address}` : ""}
          </Text>
          <Text style={{ fontSize: token("fontSizes.small"), color: token("colors.muted"), textAlign: "center" }}>
            <Link href={minimalHref(brand, "/")}>Visit {brand.name}</Link> · <Link href={minimalHref(brand, "/help")}>Get help from {brand.name}</Link>
          </Text>
        </Column>
      </Column>
    </Email>
  );
}

/** A small label in capitals, over what it names. */
function MinimalKicker({ children, color }: { children: ReactNode; color?: "primary" | "primaryForeground" | "muted" }) {
  return (
    <Text style={{ fontSize: token("fontSizes.small"), fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", color: token(`colors.${color ?? "muted"}`) }}>
      {children}
    </Text>
  );
}

// The template
function minimalReceipt(brand: Brand) {
  return template({
    id: "templates.MinimalReceiptEmail",
    version: "1.0.0",
    label: "Receipt",
    description: "A payment receipt that leads with the amount paid, then the items, the total, and how it was paid",
    guidance: "Describe each item as the customer's order names it. The total is added up for you.",
    root: "Email",
    fields: {
      ...receipt.required,
      method: prop.text({ label: "Paid with", maxLength: 40 }),
    },
    rules: minimalRules(brand),
    example: { ...receipt.example, method: "Visa ending 4242" },
    render(v) {
      const money = new Intl.NumberFormat(brand.lang ?? "en", { style: "currency", currency: v.currency });
      const total = v.items.reduce((sum, item) => sum + item.quantity * item.price, 0);
      const paid = formatDate(v.paid, brand.lang ?? "en", { month: "long", day: "numeric", year: "numeric" });
      const line = { padding: [token("spacing.sm"), 0], border: { bottom: { width: 1, style: "solid", color: token("colors.border") } } } as const;
      const quiet = { fontSize: token("fontSizes.small"), color: token("colors.muted") } as const;
      return minimalEmail(brand, {
        title: `Your ${brand.name} receipt`,
        preview: `${money.format(total)} paid on ${formatDate(v.paid, brand.lang ?? "en", { month: "long", day: "numeric" })}. Thanks.`,
        children: (
          <>
            <Column style={{ gap: token("spacing.xs"), alignItems: "center", textAlign: "center", padding: [0, 0, token("spacing.sm")] }}>
              <MinimalKicker color="primary">Payment received</MinimalKicker>
              <Heading level={1}>{money.format(total)}</Heading>
              <Text field="paid" style={{ color: token("colors.muted") }}>
                Paid on {paid}
                {v.method ? ` with ${v.method}` : ""}
              </Text>
            </Column>
            <Table field="items">
              <TableRow header>
                <TableCell style={{ ...line, ...quiet }}>Item</TableCell>
                <TableCell style={{ ...line, ...quiet, textAlign: "right", width: 110 }}>Amount</TableCell>
              </TableRow>
              {v.items.map((item, i) => (
                <TableRow key={i}>
                  <TableCell style={line}>
                    {item.description}
                    {item.quantity > 1 ? ` × ${item.quantity}` : ""}
                  </TableCell>
                  <TableCell style={{ ...line, textAlign: "right", width: 110 }}>{money.format(item.quantity * item.price)}</TableCell>
                </TableRow>
              ))}
              <TableRow>
                <TableCell style={{ padding: [token("spacing.sm"), 0], fontWeight: 700 }}>Total paid</TableCell>
                <TableCell style={{ padding: [token("spacing.sm"), 0], fontWeight: 700, textAlign: "right", width: 110 }}>{money.format(total)}</TableCell>
              </TableRow>
            </Table>
            <Row stackOnMobile={false} style={{ backgroundColor: token("colors.surface"), borderRadius: token("radii.sm"), padding: token("spacing.md"), gap: token("spacing.md") }}>
              <Column>
                <Text style={quiet}>Receipt number</Text>
                <Text field="number" style={{ fontWeight: 700 }}>{v.number}</Text>
              </Column>
              <Column>
                <Text style={{ ...quiet, textAlign: "right" }}>Date paid</Text>
                <Text style={{ fontWeight: 700, textAlign: "right" }}>{paid}</Text>
              </Column>
            </Row>
            <Text style={{ color: token("colors.muted") }}>Keep this email for your records. To ask about a charge, reply to it.</Text>
          </>
        ),
      });
    },
  });
}

export default minimalReceipt(brand);

