                  <Column>
                    <Text>{item.description}</Text>
                  </Column>
                  <Column style={{ width: 60 }}>
                    <Text style={{ color: token("colors.muted"), textAlign: "right" }}>× {String(item.quantity)}</Text>
                  </Column>
                </Row>
              ))}
            </Column>
          </>
