    fontSizes: { body: 16, small: 14 },
    lineHeights: { body: 1.6, heading: 1.2 },
    spacing: { xs: 4, sm: 8, md: 16, lg: 24, xl: 40 },
    radii: { sm: 6, md: 12 },
    elements: {
      Heading: {
        fontWeight: 700,
        by: {
          level: {
            1: { fontSize: 32, lineHeight: 1.15 },
            2: { fontSize: 24, lineHeight: 1.25 },
            3: { fontSize: 19, lineHeight: 1.25 },
          },
        },
      },
    },
  }),
  logo: { src: "https://hyperelements.dev/generated/kits/assets/brands/orbit/logo.png", width: 480, height: 120, alt: "Orbit" },
  address: "1 Main Street, Springfield",
