  lang: "en",
  fonts: [
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-400.ttf", weight: 400, style: "normal" },
    { family: "Inter", src: "https://hyperelements.dev/generated/kits/assets/fonts/Inter-700.ttf", weight: 700, style: "normal" },
  ],
};
// brand: end

// From _categories/event.ts
const event = {
  group: "Events",
  label: "Event",
  roots: ["Email", "Page", "Canvas"],
  useWhen: "An event people can come to: what it is, when and where, and how to register",
  avoidWhen: "A ticket someone already has (use ticket), or one speaker's announcement (use speaker)",
  required: {
    name: prop.text({ label: "Event name", required: true, maxLength: 60 }),
    starts: prop.date({ label: "Date", required: true }),
    time: prop.text({ label: "Time", required: true, maxLength: 40 }),
    place: prop.object(
      {
        name: prop.text({ label: "Venue", required: true, maxLength: 60 }),
        address: prop.text({ label: "Address", required: true, maxLength: 100 }),
      },
      { label: "Where", required: true },
    ),
    register: prop.link({ label: "Registration link", required: true }),
  },
  example: {
    name: "Build Day",
    starts: "2026-05-14",
    time: "9:30 AM to 6:00 PM",
    place: { name: "The Foundry", address: "120 Mill Street, Pittsburgh" },
    register: "/events/build-day",
  },
} as const;

// From summit/parts.tsx
/** A link's address: a path on the brand's site, or a full URL, with the brand's required parameters. */
function summitHref(brand: Brand, to: string | { href: string }): string {
  const url = new URL(typeof to === "string" ? to : to.href, brand.links.site);
  for (const [key, value] of Object.entries(brand.links.params ?? {})) url.searchParams.set(key, value);
  return url.toString();
}

/** The brand's link rules. */
const summitLinks = (brand: Brand) => ({ domains: brand.links.domains, ...(brand.links.params ? { params: brand.links.params } : {}) });

/** The rules a Summit email or page holds to. */
function summitScreenRules(brand: Brand) {
  return {
    plugins: { lint: lint() },
    require: { lint: ["contrast", "text-size", "link-text", "alt-text"], core: ["layout/overflow"] },
    links: summitLinks(brand),
    root: { lang: true as const },
  };
}

/** A date in the brand's language. */
const summitDate = (brand: Brand, date: string, options: Intl.DateTimeFormatOptions) => formatDate(date, brand.lang ?? "en", options);

/** A date as a badge: the month small and the day large, on the brand's surface. */
function SummitDateBadge({ brand, date, size = 1 }: { brand: Brand; date: string; size?: number }) {
  return (
    <Column style={{ width: 76 * size, backgroundColor: token("colors.surface"), borderRadius: token("radii.md"), padding: [10 * size, 0] }}>
      <Text style={{ fontSize: token("fontSizes.small"), fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", color: token("colors.primary"), textAlign: "center" }}>
        {summitDate(brand, date, { month: "short" })}
      </Text>
      <Text style={{ fontSize: 30 * size, fontWeight: 700, lineHeight: 1.1, textAlign: "center" }}>{summitDate(brand, date, { day: "numeric" })}</Text>
    </Column>
  );
}

// The template
function summitEventEmail(brand: Brand) {
  return template({
    id: "templates.SummitEventEmail",
    version: "1.0.0",
    label: "Event invitation",
    description: "An invitation: the event's name on a band of the brand's color, when and where, a button to register, and the day's schedule",
    guidance: "Lead with what the day is for. Keep the schedule to the main moments.",
    root: "Email",
    fields: {
      ...event.required,
      tagline: prop.text({ label: "Tagline", required: true, maxLength: 120 }),
      schedule: prop.list(
        prop.object({ time: prop.text({ label: "Time", required: true, maxLength: 12 }), title: prop.text({ label: "What", required: true, maxLength: 70 }) }, { label: "Moment" }),
        { label: "Schedule", min: 0, max: 6 },
      ),
    },
    rules: summitScreenRules(brand),
    example: {
      ...event.example,
      tagline: "A day of talks and workshops for the people who build and ship software.",
      schedule: [
        { time: "9:30 AM", title: "Doors open, coffee and breakfast" },
        { time: "10:00 AM", title: "Opening talk: shipping weekly without breaking anything" },
        { time: "1:00 PM", title: "Workshops, in four rooms" },
        { time: "5:00 PM", title: "Closing panel, then drinks on the roof" },
      ],
    },
    render(v) {
      const day = summitDate(brand, v.starts, { weekday: "long", month: "long", day: "numeric" });
      return (
        <Email
          width={600}
          title={`You're invited to ${v.name}`}
          previewText={`${day}, ${v.place.name}. ${v.tagline}`}
          lang={brand.lang ?? "en"}
          {...(brand.dir ? { dir: brand.dir } : {})}
          theme={brand.theme}
          fonts={brand.fonts}
          style={{ fontSize: token("fontSizes.body"), lineHeight: token("lineHeights.body") }}
        >
          <Section style={{ padding: [token("spacing.lg"), token("spacing.xl")] }}>
            <Image src={{ src: brand.logo.src, width: brand.logo.width, height: brand.logo.height }} alt={brand.logo.alt} style={{ width: 140 }} />
          </Section>
          <Section style={{ backgroundColor: token("colors.primary"), color: token("colors.primaryForeground"), padding: [token("spacing.xl"), token("spacing.xl")] }}>
            <Column style={{ gap: token("spacing.sm") }}>
              <Text style={{ fontSize: token("fontSizes.small"), fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase" }}>You're invited</Text>
              <Heading field="name" level={1} style={{ color: token("colors.primaryForeground") }}>{v.name}</Heading>
              <Text field="tagline">{v.tagline}</Text>
            </Column>
          </Section>
